package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.identity.*;
import org.springframework.mock.web.*;
import org.springframework.beans.factory.ListableBeanFactory;
import org.springframework.security.core.Authentication;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.core.env.MapPropertySource;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.ruoyi.medical.persistence.FormalInputFixture.*;
final class ExpertQualificationHttpTest {
 ExpertFixture f;ApplicationSessionIdentity identity;Authentication authentication;ExpertQualificationController controller;
 @BeforeEach void setup()throws Exception{f=new ExpertFixture();identity=mock(ApplicationSessionIdentity.class);authentication=mock(Authentication.class);when(identity.requireCurrent(any(),eq(authentication))).thenReturn(f.f.subject);controller=new ExpertQualificationController(identity,f.service,f.schema,f.f.json);}
 @AfterEach void cleanup()throws Exception{if(f!=null)f.close();}
 MockHttpServletRequest request(boolean write)throws Exception{var r=new MockHttpServletRequest();r.addHeader("X-Schema-Version","1.0.0");r.addHeader("X-Context-Revision","1");if(write){r.setMethod("POST");r.setContentType("application/json");r.addHeader("X-CSRF-TOKEN","actual-filter-handles-authentication");r.addHeader("Idempotency-Key","expert-author-original-key");r.setContent(f.schema.canonical(f.authorRequest()).getBytes(StandardCharsets.UTF_8));}return r;}
 @Test void realAuthorAndRecoveryExposeClosedNoStoreEnvelope()throws Exception{var response=new MockHttpServletResponse();var envelope=controller.author(request(true),response,authentication);assertEquals(201,response.getStatus());assertEquals("no-store",response.getHeader("Cache-Control"));assertNotNull(response.getHeader("X-Request-Id"));assertEquals("1",response.getHeader("X-Resource-Revision"));var receipt=envelope.path("data");assertTrue(receipt.has("qualification"));var recovered=controller.recover(request(false),new MockHttpServletResponse(),authentication,receipt.path("operation_id").asText());assertEquals(receipt,recovered.path("data").path("receipt"));}
 @Test void independentDecisionReportsActualQualificationRevision()throws Exception{var authored=f.author();f.actor(id(4));var r=request(true);r.removeHeader("Idempotency-Key");r.addHeader("Idempotency-Key","expert-approve-original-key");r.setContent(f.schema.canonical(f.decision(authored,"APPROVE","1")).getBytes(StandardCharsets.UTF_8));var response=new MockHttpServletResponse();var result=controller.decide(r,response,authentication);assertEquals("2",response.getHeader("X-Resource-Revision"));assertEquals("2",result.path("resource_revision").asText());var readResponse=new MockHttpServletResponse();controller.read(request(false),readResponse,authentication,authored.path("qualification").path("version_id").asText());assertEquals("2",readResponse.getHeader("X-Resource-Revision"));}
 @Test void missingDuplicateAndCommaHeadersRejectBeforeBodyOrGet()throws Exception{for(String h:java.util.List.of("X-Schema-Version","X-Context-Revision","Idempotency-Key","X-CSRF-TOKEN")){var r=request(true);r.removeHeader(h);assertThrows(SchemaRejection.class,()->controller.author(r,new MockHttpServletResponse(),authentication));var duplicate=request(true);duplicate.addHeader(h,"duplicate");assertThrows(SchemaRejection.class,()->controller.author(duplicate,new MockHttpServletResponse(),authentication));var comma=request(true);comma.removeHeader(h);comma.addHeader(h,"one,two");assertThrows(SchemaRejection.class,()->controller.author(comma,new MockHttpServletResponse(),authentication));}assertEquals(0,f.f.requests.get());verifyNoInteractions(identity);}
 @Test void unknownSchemaQueryAndReadBodyReject()throws Exception{var r=request(true);r.removeHeader("X-Schema-Version");r.addHeader("X-Schema-Version","2.0.0");assertThrows(SchemaRejection.class,()->controller.author(r,new MockHttpServletResponse(),authentication));var query=request(false);query.setQueryString("purpose=anything");assertThrows(SchemaRejection.class,()->controller.read(query,new MockHttpServletResponse(),authentication,id(808)));var body=request(false);body.setContent("{}".getBytes(StandardCharsets.UTF_8));assertThrows(SchemaRejection.class,()->controller.read(body,new MockHttpServletResponse(),authentication,id(808)));}
 @Test void oversizedRequestRejectsBeforeSessionAndTransport()throws Exception{var r=request(true);r.setContent(new byte[ExpertQualificationSchema.MAXIMUM_REQUEST_BYTES+1]);assertEquals(ErrorCode.FILE_TOO_LARGE,assertThrows(TenantAccessException.class,()->controller.author(r,new MockHttpServletResponse(),authentication)).code());verifyNoInteractions(identity);assertEquals(0,f.f.requests.get());}
 @Test void availabilityDoesNotInstantiateOrClaimQualifications()throws Exception{var beans=mock(ListableBeanFactory.class);when(beans.getBeanNamesForType(ExpertQualificationController.class,false,false)).thenReturn(new String[0]);var availability=new ExpertQualificationFeatureAvailability(f.f.access,beans,f.schema);var view=availability.read(f.f.subject,"1");assertFalse(view.path("enabled").asBoolean());assertEquals("FEATURE_DISABLED",view.path("unavailable_reason").asText());assertFalse(view.path("creates_professional_licence").asBoolean());assertFalse(view.path("creates_scores").asBoolean());assertFalse(view.path("proves_formal_execution").asBoolean());verify(beans).getBeanNamesForType(ExpertQualificationController.class,false,false);assertEquals(0,f.f.requests.get());assertTrue(f.journals.isEmpty());}
 @Test void availabilityReflectsRegisteredControllerAndCurrentContext()throws Exception{var beans=mock(ListableBeanFactory.class);when(beans.getBeanNamesForType(ExpertQualificationController.class,false,false)).thenReturn(new String[]{"expertController"});var availability=new ExpertQualificationFeatureAvailability(f.f.access,beans,f.schema);assertTrue(availability.read(f.f.subject,"1").path("enabled").asBoolean());assertThrows(TenantAccessException.class,()->availability.read(f.f.subject,"2"));var endpoint=new ExpertQualificationFeatureAvailabilityController(identity,availability);var response=new MockHttpServletResponse();var result=endpoint.read(request(false),response,authentication);assertTrue(result.path("data").path("enabled").asBoolean());assertNotNull(response.getHeader("X-Request-Id"));assertEquals("no-store",response.getHeader("Cache-Control"));}
 @Test void actualSpringDefaultsOffWithoutConstructingDependencies(){try(var context=new AnnotationConfigApplicationContext()){context.register(ExpertQualificationService.class,ExpertQualificationController.class,ExpertQualificationAuthority.class,ExpertQualificationEvidenceReader.class,ExpertQualificationStore.class,ExpertScoreAuthorityRecorder.class);context.refresh();assertEquals(0,context.getBeanNamesForType(ExpertQualificationService.class).length);assertEquals(0,context.getBeanNamesForType(EvaluationService.OriginalScoreWitnessSink.class).length);}}
 @Test void actualSpringEnabledControllerResolvesRealLocalSchema(){try(var context=new AnnotationConfigApplicationContext()){context.getEnvironment().getPropertySources().addFirst(new MapPropertySource("offline",Map.of("medical.expert-qualification.enabled","true")));context.registerBean(ApplicationSessionIdentity.class,()->identity);context.registerBean(ExpertQualificationService.class,()->f.service);context.registerBean(PermissionSchema.class,()->f.f.json);context.register(ExpertQualificationSchema.class,ExpertQualificationController.class);context.refresh();assertNotNull(context.getBean(ExpertQualificationController.class));assertNotNull(context.getBean(ExpertQualificationSchema.class));}}
 @Test void errorMappingPreservesSafeStructuredCodes()throws Exception{for(var entry:Map.of(ErrorCode.ACCESS_DENIED,403,ErrorCode.FILE_TOO_LARGE,413,ErrorCode.OBJECT_UNAVAILABLE,404,ErrorCode.CONTENT_MISMATCH,409).entrySet()){var response=new MockHttpServletResponse();controller.failed(new TenantAccessException(entry.getKey()),response);assertEquals(entry.getValue(),response.getStatus());assertFalse(response.getContentAsString().contains("Exception"));}}
}
